def hasMatch(s: str, p: str) -> bool:
    star_index = p.index('*')
    prefix = p[:star_index]
    suffix = p[star_index + 1:]
    prefix_len = len(prefix)
    suffix_len = len(suffix)
    # Check if the prefix can be matched
    for i in range(len(s) - prefix_len - suffix_len + 1):
        if s[i:i + prefix_len] == prefix:
            # Check if the suffix can be matched
            if s[i + prefix_len:i + prefix_len + suffix_len] == suffix:
                return True
            # Check if we can match suffix after some characters
            if suffix_len == 0 or s[i + prefix_len + len(suffix):].find(suffix) != -1:
                return True
    return False

