from typing import List


def largestInteger(nums: List[int], k: int) -> int:
    from collections import defaultdict
    count = defaultdict(int)
    n = len(nums)

    # Count occurrences of each number in all subarrays of size k
    for i in range(n - k + 1):
        unique_numbers = set(nums[i:i + k])
        for num in unique_numbers:
            count[num] += 1

    # Find the largest number with exactly one occurrence
    result = -1
    for num, occurrences in count.items():
        if occurrences == 1:
            result = max(result, num)

    return result

