from typing import List


def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]
    dp[0][0][0] = max(coins[0][0], 0)  # Start with max(0, starting coins)

    for i in range(m):
        for j in range(n):
            for k in range(3):  # k represents the number of robbers neutralized
                if i == 0 and j == 0:
                    continue  # Skip starting cell already initialized

                # Update from top cell
                if i > 0:
                    new_coins = dp[i-1][j][k] + (max(coins[i][j], 0) if coins[i][j] >= 0 else 0)
                    if coins[i][j] < 0 and k > 0:
                        # If it is a robber and we have neutralizations left
                        new_coins = max(new_coins, dp[i-1][j][k-1])
                    dp[i][j][k] = max(dp[i][j][k], new_coins)

                # Update from left cell
                if j > 0:
                    new_coins = dp[i][j-1][k] + (max(coins[i][j], 0) if coins[i][j] >= 0 else 0)
                    if coins[i][j] < 0 and k > 0:
                        new_coins = max(new_coins, dp[i][j-1][k-1])
                    dp[i][j][k] = max(dp[i][j][k], new_coins)

                # If it's a robber without using any neutralization
                if coins[i][j] < 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j][k] + coins[i][j])

    # Get the maximum coins collected at the bottom-right corner with at most 2 neutralizations
    return max(dp[m-1][n-1][0], dp[m-1][n-1][1], dp[m-1][n-1][2])

