from typing import List


def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    # Binary search to find the minimum possible maximum weight
    left, right = 1, 10**6

    def can_form_graph(max_weight: int) -> bool:
        from collections import defaultdict, deque

        # Create a graph with edges filtered by max_weight
        graph = defaultdict(list)
        in_degree = [0] * n

        for A, B, W in edges:
            if W <= max_weight:
                graph[B].append(A)  # Reverse direction to check if all nodes can reach 0
                in_degree[A] += 1  # Track in-degrees instead of out-degrees

        # BFS/DFS to check reachability to node 0 from all other nodes
        queue = deque([0])
        reachable = set([0])

        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor not in reachable:
                    reachable.add(neighbor)
                    queue.append(neighbor)

        # Check if all nodes can reach 0
        if len(reachable) != n:
            return False

        # Check if the in-degrees of each node respect the threshold
        for A in range(n):
            if in_degree[A] > threshold:
                return False

        return True

    # Perform binary search to find the minimum possible maximum weight
    while left < right:
        mid = (left + right) // 2
        if can_form_graph(mid):
            right = mid
        else:
            left = mid + 1

    return left if can_form_graph(left) else -1

