from typing import List


def maxFreeTime(eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
    n = len(startTime)
    gaps = []

    # Calculate free time gaps before, between and after meetings
    if startTime[0] > 0:
        gaps.append(startTime[0])  # Free time before the first meeting

    for i in range(1, n):
        gaps.append(startTime[i] - endTime[i - 1])  # Free time between consecutive meetings

    if endTime[-1] < eventTime:
        gaps.append(eventTime - endTime[-1])  # Free time after the last meeting

    # Calculate the maximum free time possible after rescheduling up to k meetings
    max_free_time = 0
    gaps.sort(reverse=True)

    # Rescheduling can combine k+1 gaps
    for i in range(min(k + 1, len(gaps))):
        if i < len(gaps):
            max_free_time += gaps[i]

    return max_free_time

def maxDistance(s: str, k: int) -> int:
    x, y = 0, 0
    best = 0
    for steps, char in enumerate(s, 1):
        if char == 'N':
            y += 1
        elif char == 'S':
            y -= 1
        elif char == 'E':
            x += 1
        elif char == 'W':
            x -= 1
        # Calculate the current distance and the best possible distance with changes
        current_distance = abs(x) + abs(y)
        achievable_distance = min(steps, current_distance + 2 * k)
        best = max(best, achievable_distance)
    return best

